  "content": "{\n  \"$schema\": \"https://json-schema.org/draft/2020-12/schema\",\n  \"$id\": \"https://github.com/chinchiang/GartnerPreemptiveCybersecurity_Claude/skills/shared/input-schema.json\",\n  \"title\": \"Preemptive Exposure Analysis — Input Bundle\",\n  \"description\": \"五平台共用的輸入格式。scope 與 assets 為必要；其餘為建議。所有內容皆須在授權範圍內。\",\n  \"type\": \"object\",\n  \"required\": [\"scope\", \"assets\"],\n  \"properties\": {\n    \"scope\": {\n      \"type\": \"object\",\n      \"required\": [\"organization\", \"analysis_date\", \"authorized_scope\", \"reporting\"],\n      \"properties\": {\n        \"organization\": { \"type\": \"string\" },\n        \"analysis_date\": { \"type\": \"string\", \"format\": \"date\" },\n        \"authorized_scope\": {\n          \"type\": \"object\",\n          \"required\": [\"in_scope_assets\", \"active_testing_authorized\", \"external_scanning_authorized\"],\n          \"properties\": {\n            \"in_scope_assets\": { \"type\": \"array\", \"items\": { \"type\": \"string\" }, \"minItems\": 1 },\n            \"excluded\": { \"type\": \"array\", \"items\": { \"type\": \"string\" } },\n            \"active_testing_authorized\": { \"type\": \"boolean\" },\n            \"external_scanning_authorized\": { \"type\": \"boolean\" },\n            \"authorizer\": { \"type\": \"string\" },\n            \"authorization_reference\": { \"type\": \"string\" }\n          }\n        },\n        \"risk_appetite\": { \"type\": \"object\" },\n        \"reporting\": {\n          \"type\": \"object\",\n          \"required\": [\"audience\"],\n          \"properties\": {\n            \"audience\": { \"type\": \"array\", \"items\": { \"type\": \"string\" } },\n            \"language\": { \"type\": \"string\", \"default\": \"zh-TW\" },\n            \"mask_identifiers\": { \"type\": \"boolean\", \"default\": true },\n            \"cadence\": { \"type\": \"string\" }\n          }\n        }\n      }\n    },\n    \"assets\": {\n      \"type\": \"array\",\n      \"minItems\": 1,\n      \"items\": {\n        \"type\": \"object\",\n        \"required\": [\"asset_id\", \"name\", \"type\", \"business_criticality\", \"internet_exposed\", \"owner\"],\n        \"properties\": {\n          \"asset_id\": { \"type\": \"string\" },\n          \"name\": { \"type\": \"string\" },\n          \"type\": { \"type\": \"string\" },\n          \"environment\": { \"type\": \"string\" },\n          \"owner\": { \"type\": \"string\" },\n          \"business_criticality\": { \"type\": \"integer\", \"minimum\": 1, \"maximum\": 5 },\n          \"data_classification\": { \"type\": \"string\", \"enum\": [\"Public\", \"Internal\", \"Confidential\", \"Restricted\"] },\n          \"internet_exposed\": { \"type\": \"boolean\" },\n          \"os_or_platform\": { \"type\": \"string\" },\n          \"notes\": { \"type\": \"string\" }\n        }\n      }\n    },\n    \"vulnerabilities\": {\n      \"type\": \"array\",\n      \"items\": {\n        \"type\": \"object\",\n        \"required\": [\"finding_id\", \"asset_id\", \"vuln_id\", \"title\", \"cvss_base\"],\n        \"properties\": {\n          \"finding_id\": { \"type\": \"string\" },\n          \"asset_id\": { \"type\": \"string\" },\n          \"vuln_id\": { \"type\": \"string\" },\n          \"title\": { \"type\": \"string\" },\n          \"cvss_base\": { \"type\": \"number\", \"minimum\": 0, \"maximum\": 10 },\n          \"exploit_public\": { \"type\": \"boolean\" },\n          \"epss\": { \"type\": \"number\", \"minimum\": 0, \"maximum\": 1 },\n          \"kev\": { \"type\": \"boolean\" },\n          \"first_seen\": { \"type\": \"string\", \"format\": \"date\" },\n          \"patch_available\": { \"type\": \"boolean\" },\n          \"notes\": { \"type\": \"string\" }\n        }\n      }\n    },\n    \"exposures\": { \"type\": \"object\", \"properties\": { \"as_of\": { \"type\": \"string\" }, \"exposures\": { \"type\": \"array\", \"items\": { \"type\": \"object\", \"properties\": { \"asset_id\": { \"type\": [\"string\", \"null\"] }, \"hostname\": { \"type\": \"string\" }, \"ip\": { \"type\": [\"string\", \"null\"] }, \"ports\": { \"type\": \"array\", \"items\": { \"type\": \"integer\" } }, \"fingerprint\": { \"type\": \"string\" }, \"issues\": { \"type\": \"array\", \"items\": { \"type\": \"string\" } } } } } } },\n    \"identities\": { \"type\": \"array\", \"items\": { \"type\": \"object\", \"required\": [\"identity_id\", \"account\", \"privilege_level\", \"linked_assets\"], \"properties\": { \"identity_id\": { \"type\": \"string\" }, \"account\": { \"type\": \"string\" }, \"type\": { \"type\": \"string\" }, \"privilege_level\": { \"type\": \"string\" }, \"mfa_enabled\": { \"type\": [\"boolean\", \"string\"] }, \"last_login_days\": { \"type\": \"integer\" }, \"linked_assets\": { \"type\": \"string\", \"description\": \"以分號分隔的 asset_id\" }, \"notes\": { \"type\": \"string\" } } } },\n    \"misconfigurations\": { \"type\": \"array\", \"items\": { \"type\": \"object\", \"required\": [\"config_id\", \"asset_id\", \"control\", \"status\"], \"properties\": { \"config_id\": { \"type\": \"string\" }, \"asset_id\": { \"type\": \"string\" }, \"benchmark\": { \"type\": \"string\" }, \"control\": { \"type\": \"string\" }, \"status\": { \"type\": \"string\", \"enum\": [\"pass\", \"fail\", \"unknown\"] }, \"severity\": { \"type\": \"string\" } } } },\n    \"controls\": { \"type\": \"object\", \"properties\": { \"as_of\": { \"type\": \"string\" }, \"controls\": { \"type\": \"array\", \"items\": { \"type\": \"object\", \"required\": [\"control_id\", \"name\", \"coverage_assets\", \"gaps\", \"maturity\"], \"properties\": { \"control_id\": { \"type\": \"string\" }, \"name\": { \"type\": \"string\" }, \"coverage_assets\": { \"type\": \"array\", \"items\": { \"type\": \"string\" } }, \"gaps\": { \"type\": \"array\", \"items\": { \"type\": \"string\" } }, \"maturity\": { \"type\": \"string\", \"enum\": [\"none\", \"basic\", \"partial\", \"managed\", \"optimized\"] }, \"notes\": { \"type\": \"string\" } } } } } },\n    \"threat_intel\": { \"type\": \"object\", \"properties\": { \"as_of\": { \"type\": \"string\" }, \"sector\": { \"type\": \"string\" }, \"actors\": { \"type\": \"array\", \"items\": { \"type\": \"object\", \"required\": [\"actor_id\", \"name\", \"ttps\", \"exploits_vuln_ids\"], \"properties\": { \"actor_id\": { \"type\": \"string\" }, \"name\": { \"type\": \"string\" }, \"motivation\": { \"type\": \"string\" }, \"targets_sector\": { \"type\": \"boolean\" }, \"confidence\": { \"type\": \"string\", \"enum\": [\"low\", \"medium\", \"high\"] }, \"ttps\": { \"type\": \"array\", \"items\": { \"type\": \"string\" } }, \"exploits_vuln_ids\": { \"type\": \"array\", \"items\": { \"type\": \"string\" } }, \"recent_activity\": { \"type\": \"string\" } } } }, \"trending_weakness_classes\": { \"type\": \"array\", \"items\": { \"type\": \"string\" } } } },\n    \"topology\": { \"type\": \"object\", \"required\": [\"crown_jewels\", \"edges\"], \"properties\": { \"crown_jewels\": { \"type\": \"array\", \"items\": { \"type\": \"string\" } }, \"edges\": { \"type\": \"array\", \"items\": { \"type\": \"object\", \"required\": [\"from\", \"to\", \"via\", \"trust\"], \"properties\": { \"from\": { \"type\": \"string\" }, \"to\": { \"type\": \"string\" }, \"via\": { \"type\": \"string\" }, \"trust\": { \"type\": \"string\", \"enum\": [\"exposed\", \"network\", \"identity\", \"app-trust\", \"misconfig\", \"user-pivot\", \"data\"] } } } } } }\n  }\n}\n"
